package com.rohit.inventory.controller; import com.rohit.inventory.dto.request.NotificationPreferenceRequest; import com.rohit.inventory.dto.response.ApiResponse; import com.rohit.inventory.entity.NotificationPreference; import com.rohit.inventory.repository.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/notifications/preferences") public class NotificationPreferenceController { private final NotificationPreferenceRepository prefs; private final UserRepository users; public NotificationPreferenceController(NotificationPreferenceRepository prefs,UserRepository users){this.prefs=prefs;this.users=users;} @GetMapping @PreAuthorize("hasAuthority('NOTIFICATION_READ') or hasAuthority('INVENTORY_READ')") public ApiResponse<List<Map<String,Object>>> list(@AuthenticationPrincipal UserDetails u){UUID id=users.findByEmail(u.getUsername()).orElseThrow().getId();return ApiResponse.success("Notification preferences retrieved successfully",prefs.findByUserId(id).stream().map(p->Map.<String,Object>of("notificationType",p.getNotificationType(),"enabled",p.isEnabled())).toList());} @PutMapping @PreAuthorize("hasAuthority('NOTIFICATION_UPDATE') or hasAuthority('INVENTORY_READ')") public ApiResponse<Map<String,Object>> update(@Valid @RequestBody NotificationPreferenceRequest r,@AuthenticationPrincipal UserDetails u){var user=users.findByEmail(u.getUsername()).orElseThrow();var p=prefs.findByUserIdAndNotificationType(user.getId(),r.notificationType()).orElseGet(()->{var x=new NotificationPreference();x.setUser(user);x.setNotificationType(r.notificationType());return x;});p.setEnabled(r.enabled());prefs.save(p);return ApiResponse.success("Notification preference updated",Map.of("notificationType",p.getNotificationType(),"enabled",p.isEnabled()));} }
